from __future__ import annotations

from itertools import pairwise
from pathlib import Path
from typing import Any

try:
    from docx import Document
    from docx.enum.text import WD_ALIGN_PARAGRAPH
    from docx.oxml import OxmlElement
    from docx.oxml.ns import qn
    from docx.shared import Inches, Pt, RGBColor
    from docx.text.run import Run
except ImportError as exc:  # pragma: no cover - dependency check path
    Document = None  # type: ignore[assignment]
    Run = None  # type: ignore[assignment]
    DOCX_IMPORT_ERROR = exc
else:
    DOCX_IMPORT_ERROR = None

from .constants import (
    BLUE,
    DOC_CONTENT_WIDTH_PT,
    DOCX_MARGIN_IN,
    INK,
    MUTED,
    NEGATIVE,
    POSITIVE,
    SOFT_BG,
)
from .table_utils import numeric_table_columns

DOCX_CONTENT_WIDTH_IN = round(DOC_CONTENT_WIDTH_PT / 72, 2)
EMU_PER_INCH = 914400


def require_docx() -> None:
    if DOCX_IMPORT_ERROR is not None:
        raise SystemExit(
            "DOCX upload mode requires python-docx. Install it in the active Python "
            "environment before running this helper."
        ) from DOCX_IMPORT_ERROR


def rgb_color(color: dict[str, float]) -> RGBColor:
    return RGBColor(
        round(color["red"] * 255),
        round(color["green"] * 255),
        round(color["blue"] * 255),
    )


def hex_color(color: dict[str, float]) -> str:
    return "".join(f"{round(color[channel] * 255):02X}" for channel in ("red", "green", "blue"))


def shade_cell(cell: Any, color: dict[str, float]) -> None:
    tc_pr = cell._tc.get_or_add_tcPr()
    shd = tc_pr.find(qn("w:shd"))
    if shd is None:
        shd = OxmlElement("w:shd")
        tc_pr.append(shd)
    shd.set(qn("w:fill"), hex_color(color))


def set_cell_width(cell: Any, width_twips: int) -> None:
    tc_pr = cell._tc.get_or_add_tcPr()
    tc_w = tc_pr.find(qn("w:tcW"))
    if tc_w is None:
        tc_w = OxmlElement("w:tcW")
        tc_pr.append(tc_w)
    tc_w.set(qn("w:w"), str(width_twips))
    tc_w.set(qn("w:type"), "dxa")


def use_portable_bullet_glyphs(document: Any) -> None:
    numbering = document.part.numbering_part.element
    for abstract_num in numbering.findall(qn("w:abstractNum")):
        for level in abstract_num.findall(qn("w:lvl")):
            num_fmt = level.find(qn("w:numFmt"))
            if num_fmt is None or num_fmt.get(qn("w:val")) != "bullet":
                continue

            level_text = level.find(qn("w:lvlText"))
            if level_text is None:
                level_text = OxmlElement("w:lvlText")
                level.append(level_text)
            level_text.set(qn("w:val"), "\u2022")

            run_props = level.find(qn("w:rPr"))
            if run_props is None:
                run_props = OxmlElement("w:rPr")
                level.append(run_props)
            run_fonts = run_props.find(qn("w:rFonts"))
            if run_fonts is None:
                run_fonts = OxmlElement("w:rFonts")
                run_props.append(run_fonts)
            for font_attr in ("ascii", "hAnsi", "eastAsia", "cs"):
                run_fonts.set(qn(f"w:{font_attr}"), "Arial")
            run_fonts.attrib.pop(qn("w:hint"), None)


def add_hyperlink(paragraph: Any, text: str, url: str) -> Any:
    part = paragraph.part
    rel_id = part.relate_to(
        url,
        "http://schemas.openxmlformats.org/officeDocument/2006/relationships/hyperlink",
        is_external=True,
    )
    hyperlink = OxmlElement("w:hyperlink")
    hyperlink.set(qn("r:id"), rel_id)
    run_element = OxmlElement("w:r")
    text_element = OxmlElement("w:t")
    text_element.text = text
    run_element.append(text_element)
    hyperlink.append(run_element)
    paragraph._p.append(hyperlink)
    return Run(run_element, paragraph)


def active_inline_styles(
    inline_styles: list[dict[str, Any]], start: int, end: int
) -> list[dict[str, Any]]:
    return [style for style in inline_styles if style["start"] < end and style["end"] > start]


def style_boundaries(inline_styles: list[dict[str, Any]], start: int, end: int) -> list[int]:
    boundaries = {start, end}
    for style in active_inline_styles(inline_styles, start, end):
        boundaries.add(max(start, style["start"]))
        boundaries.add(min(end, style["end"]))
    return sorted(boundaries)


def apply_run_styles(run: Any, styles: list[dict[str, Any]], default_bold: bool = False) -> None:
    style_names = {style["style"] for style in styles}
    run.font.name = "Arial"
    run.font.size = Pt(11)
    run.font.color.rgb = rgb_color(INK)
    run.bold = default_bold or "bold" in style_names
    run.italic = "italic" in style_names
    if "code" in style_names:
        run.font.name = "Courier New"
    if "positive" in style_names:
        run.font.color.rgb = rgb_color(POSITIVE)
    elif "negative" in style_names:
        run.font.color.rgb = rgb_color(NEGATIVE)
    elif "muted" in style_names:
        run.font.color.rgb = rgb_color(MUTED)
    elif "link" in style_names:
        run.font.color.rgb = rgb_color(BLUE)
        run.underline = True


def add_rich_text(
    paragraph: Any,
    text: str,
    start: int,
    inline_styles: list[dict[str, Any]],
    default_bold: bool = False,
) -> None:
    end = start + len(text)
    boundaries = style_boundaries(inline_styles, start, end)
    for seg_start, seg_end in pairwise(boundaries):
        segment = text[seg_start - start : seg_end - start]
        if not segment:
            continue
        styles = active_inline_styles(inline_styles, seg_start, seg_end)
        link = next((style for style in styles if style["style"] == "link"), None)
        if link:
            run = add_hyperlink(paragraph, segment, link["url"])
        else:
            run = paragraph.add_run(segment)
        apply_run_styles(run, styles, default_bold=default_bold)


def add_cell_text(
    cell: Any,
    text: str,
    styles: list[str],
    links: list[dict[str, Any]],
    is_header: bool = False,
) -> None:
    paragraph = cell.paragraphs[0]
    paragraph.text = ""
    paragraph.paragraph_format.space_after = Pt(0)
    inline_styles: list[dict[str, Any]] = []
    for link in links:
        inline_styles.append(
            {
                "start": link["start"],
                "end": link["end"],
                "style": "link",
                "url": link["url"],
            }
        )
    whole_cell_styles = set(styles)
    for style in whole_cell_styles & {"code", "positive", "negative"}:
        inline_styles.append({"start": 0, "end": len(text), "style": style})
    add_rich_text(paragraph, text, 0, inline_styles, default_bold=is_header or "bold" in styles)


def page_text_width_in(section: Any) -> float:
    return (
        int(section.page_width) - int(section.left_margin) - int(section.right_margin)
    ) / EMU_PER_INCH


def add_table(document: Any, table_info: dict[str, Any], content_width_in: float) -> None:
    rows = table_info["rows"]
    if not rows:
        return
    column_count = max(len(row) for row in rows)
    table = document.add_table(rows=len(rows), cols=column_count)
    table.style = "Table Grid"
    table.autofit = False
    numeric_columns = numeric_table_columns(rows)
    width_twips = round(content_width_in * 1440 / max(column_count, 1))
    cell_styles = table_info.get("cell_styles", [[[] for _ in row] for row in rows])
    cell_links = table_info.get("cell_links", [[[] for _ in row] for row in rows])

    for row_index, row in enumerate(rows):
        for col_index in range(column_count):
            cell = table.cell(row_index, col_index)
            set_cell_width(cell, width_twips)
            text = row[col_index] if col_index < len(row) else ""
            styles = (
                cell_styles[row_index][col_index]
                if row_index < len(cell_styles) and col_index < len(cell_styles[row_index])
                else []
            )
            links = (
                cell_links[row_index][col_index]
                if row_index < len(cell_links) and col_index < len(cell_links[row_index])
                else []
            )
            is_header = row_index == 0 and table_info.get("kind") == "table"
            add_cell_text(cell, text, styles, links, is_header=is_header)
            if is_header:
                shade_cell(cell, SOFT_BG)
            if col_index in numeric_columns:
                cell.paragraphs[0].alignment = WD_ALIGN_PARAGRAPH.RIGHT
    document.add_paragraph()


def add_chart_image(
    document: Any, chart: dict[str, Any], out_dir: Path, content_width_in: float
) -> None:
    image_path = out_dir / chart["image_file"]
    if not image_path.exists():
        document.add_paragraph(f"[Missing chart image: {chart.get('id', image_path.name)}]")
        return
    paragraph = document.add_paragraph()
    paragraph.alignment = WD_ALIGN_PARAGRAPH.LEFT
    run = paragraph.add_run()
    chart_width_in = min(
        float(chart.get("docs_width_pt") or DOC_CONTENT_WIDTH_PT) / 72,
        content_width_in,
    )
    run.add_picture(str(image_path), width=Inches(chart_width_in))


def paragraph_kind(
    start: int,
    end: int,
    headings: list[dict[str, Any]],
    blocks: list[dict[str, Any]],
    lists: list[dict[str, Any]],
) -> tuple[str, dict[str, Any] | None]:
    for heading in headings:
        if heading["start"] == start and heading["end"] == end:
            return "heading", heading
    for item in lists:
        if item["start"] <= start and end <= item["end"]:
            return "ordered_list" if item.get("ordered") else "bullet_list", item
    for block in blocks:
        if block["start"] <= start and end <= block["end"]:
            return block["type"], block
    return "paragraph", None


def add_text_paragraph(
    document: Any,
    text: str,
    start: int,
    end: int,
    manifest: dict[str, Any],
) -> None:
    kind, metadata = paragraph_kind(
        start,
        end,
        manifest["headings"],
        manifest["blocks"],
        manifest["lists"],
    )
    if kind == "heading":
        level = min(max(int(metadata["level"]), 1), 3) if metadata else 2
        paragraph = document.add_heading(level=level)
        default_bold = True
    elif kind == "bullet_list":
        paragraph = document.add_paragraph(style="List Bullet")
        default_bold = False
    elif kind == "ordered_list":
        paragraph = document.add_paragraph(style="List Number")
        default_bold = False
    else:
        paragraph = document.add_paragraph()
        default_bold = kind == "summary_callout"

    paragraph.paragraph_format.space_after = Pt(6)
    if kind in {"muted", "note", "source_list"}:
        inline_styles = list(manifest["inline_styles"]) + [
            {"start": start, "end": end, "style": "muted"}
        ]
    else:
        inline_styles = manifest["inline_styles"]
    add_rich_text(paragraph, text, start, inline_styles, default_bold=default_bold)
    if kind in {"muted", "note", "source_list"}:
        for run in paragraph.runs:
            run.font.size = Pt(9)
            if not run.font.color.rgb:
                run.font.color.rgb = rgb_color(MUTED)


def write_docx(manifest: dict[str, Any], out_dir: Path, file_name: str = "report.docx") -> Path:
    require_docx()
    assert Document is not None

    document = Document()
    section = document.sections[0]
    section.top_margin = Inches(DOCX_MARGIN_IN)
    section.bottom_margin = Inches(DOCX_MARGIN_IN)
    section.left_margin = Inches(DOCX_MARGIN_IN)
    section.right_margin = Inches(DOCX_MARGIN_IN)
    content_width_in = min(DOCX_CONTENT_WIDTH_IN, page_text_width_in(section))
    normal_style = document.styles["Normal"]
    normal_style.font.name = "Arial"
    normal_style.font.size = Pt(11)
    use_portable_bullet_glyphs(document)

    table_by_placeholder = {table["placeholder"]: table for table in manifest["tables"]}
    chart_by_placeholder = {chart["placeholder"]: chart for chart in manifest["chart_images"]}

    offset = 0
    for raw_line in manifest["skeleton_text"].splitlines(keepends=True):
        line = raw_line.rstrip("\n")
        line_start = offset
        line_end = line_start + len(line)
        offset += len(raw_line)
        if not line.strip():
            continue
        if line in table_by_placeholder:
            add_table(document, table_by_placeholder[line], content_width_in)
            continue
        if line in chart_by_placeholder:
            add_chart_image(document, chart_by_placeholder[line], out_dir, content_width_in)
            continue
        add_text_paragraph(document, line, line_start, line_end, manifest)

    docx_path = out_dir / file_name
    document.save(docx_path)
    return docx_path

from __future__ import annotations

import re
from pathlib import Path
from typing import Any

try:
    from bs4 import BeautifulSoup, NavigableString, Tag
except ImportError as exc:  # pragma: no cover - dependency check path
    BeautifulSoup = NavigableString = Tag = None  # type: ignore[assignment,misc]
    BS4_IMPORT_ERROR = exc
else:
    BS4_IMPORT_ERROR = None

from .constants import DOC_CONTENT_WIDTH_PT, SVG_REPORT_STYLE_DEFAULTS
from .model import Builder
from .utils import collapse_ws

FONT_WEIGHT_BOLD_RE = re.compile(r"font-weight\s*:\s*([^;}\s]+)", re.IGNORECASE)
CSS_RULE_RE = re.compile(r"([^{}]+)\{([^{}]*)\}", re.DOTALL)


def require_bs4() -> None:
    if BS4_IMPORT_ERROR is not None:
        raise SystemExit(
            "This helper requires beautifulsoup4. Install it in the active Python "
            "environment before running this helper."
        ) from BS4_IMPORT_ERROR


def append_text(builder: Builder, text: str) -> None:
    text = collapse_ws(text)
    if not text:
        return
    if text.isspace():
        if builder.offset and not builder.text().endswith((" ", "\n")):
            builder.add(" ")
        return
    if builder.offset and not builder.text().endswith((" ", "\n")) and text[0] not in " .,;:!?)%]":
        builder.add(" ")
    builder.add(text)


def classes(node: Tag) -> set[str]:
    raw = node.get("class") or []
    return set(raw if isinstance(raw, list) else str(raw).split())


def direct_tag_children(node: Tag) -> list[Tag]:
    return [child for child in node.children if isinstance(child, Tag)]


def direct_children_with_class(node: Tag, class_name: str) -> list[Tag]:
    return [child for child in direct_tag_children(node) if class_name in classes(child)]


def font_weight_is_bold(value: str) -> bool:
    value = value.strip().lower()
    if value in {"bold", "bolder"}:
        return True
    try:
        return int(value) >= 600
    except ValueError:
        return False


def inline_style_is_bold(style: str | None) -> bool:
    if not style:
        return False
    match = FONT_WEIGHT_BOLD_RE.search(style)
    return bool(match and font_weight_is_bold(match.group(1)))


def table_first_column_is_bold(raw_html: str) -> bool:
    accepted_selectors = {
        "td:first-child",
        "td:nth-child(1)",
        "tbody td:first-child",
        "tbody td:nth-child(1)",
        "table td:first-child",
        "table td:nth-child(1)",
        "table tbody td:first-child",
        "table tbody td:nth-child(1)",
    }
    for selectors, body in CSS_RULE_RE.findall(raw_html):
        weight = FONT_WEIGHT_BOLD_RE.search(body)
        if not weight or not font_weight_is_bold(weight.group(1)):
            continue
        normalized_selectors = {
            re.sub(r"\s+", " ", selector.strip().lower()) for selector in selectors.split(",")
        }
        if normalized_selectors & accepted_selectors:
            return True
    return False


def append_inline(builder: Builder, node: Tag | NavigableString) -> None:
    if isinstance(node, NavigableString):
        append_text(builder, str(node))
        return
    if not isinstance(node, Tag):
        return

    before = builder.offset
    for child in node.children:
        append_inline(builder, child)
    after = builder.offset
    if after <= before:
        return

    tag_classes = classes(node)
    styles: list[str] = []
    if node.name in {"strong", "b"}:
        styles.append("bold")
    if node.name in {"em", "i"}:
        styles.append("italic")
    if node.name == "code":
        styles.append("code")
    if "positive" in tag_classes:
        styles.append("positive")
    if "negative" in tag_classes:
        styles.append("negative")
    if node.name == "a" and node.get("href"):
        styles.append("link")

    for style in styles:
        entry: dict[str, Any] = {
            "start": before,
            "end": after,
            "style": style,
            "text": builder.text()[before:after],
        }
        if style == "link":
            entry["url"] = node["href"]
        builder.inline_styles.append(entry)


def add_paragraph(builder: Builder, node: Tag, block_type: str | None = None) -> None:
    start = builder.offset
    append_inline(builder, node)
    end = builder.offset
    if end > start:
        builder.add("\n")
        if block_type:
            builder.blocks.append({"start": start, "end": end + 1, "type": block_type})


def add_heading(builder: Builder, node: Tag) -> None:
    start = builder.offset
    append_inline(builder, node)
    end = builder.offset
    level = int(node.name[1]) if node.name and node.name[1:].isdigit() else 2
    builder.add("\n")
    builder.headings.append(
        {"start": start, "end": end, "level": level, "text": builder.text()[start:end]}
    )


def cell_text_styles_and_links(
    cell: Tag, first_column_bold: bool = False
) -> tuple[str, list[str], list[dict[str, Any]]]:
    local_builder = Builder()
    append_inline(local_builder, cell)
    raw_text = local_builder.text()
    leading_trim = len(raw_text) - len(raw_text.lstrip())
    text = raw_text.strip()
    styles = []
    if cell.find(["strong", "b"]) or cell.name == "th" or inline_style_is_bold(cell.get("style")):
        styles.append("bold")
    if first_column_bold and cell.name == "td" and "bold" not in styles:
        styles.append("bold")
    if cell.find("code"):
        styles.append("code")
    cell_classes = classes(cell)
    if "positive" in cell_classes or "pos" in cell_classes or "strong" in cell_classes:
        styles.append("positive")
    if "negative" in cell_classes or "neg" in cell_classes or "weak" in cell_classes:
        styles.append("negative")
    if "neutral" in cell_classes:
        styles.append("neutral")
    links = []
    for style in local_builder.inline_styles:
        if style.get("style") != "link":
            continue
        start = max(0, style["start"] - leading_trim)
        end = min(len(text), style["end"] - leading_trim)
        while start < end and text[start].isspace():
            start += 1
        while end > start and text[end - 1].isspace():
            end -= 1
        if start >= end:
            continue
        links.append(
            {
                "start": start,
                "end": end,
                "url": style["url"],
                "text": text[start:end],
            }
        )
    return text, styles, links


def table_from_html(
    node: Tag,
    first_column_bold: bool = False,
) -> tuple[list[list[str]], list[list[list[str]]], list[list[list[dict[str, Any]]]]]:
    rows: list[list[str]] = []
    styles: list[list[list[str]]] = []
    links: list[list[list[dict[str, Any]]]] = []
    for tr in node.find_all("tr"):
        row: list[str] = []
        style_row: list[list[str]] = []
        link_row: list[list[dict[str, Any]]] = []
        for cell_index, cell in enumerate(tr.find_all(["th", "td"], recursive=False)):
            text, cell_styles, cell_links = cell_text_styles_and_links(
                cell, first_column_bold=first_column_bold and cell_index == 0
            )
            row.append(text)
            style_row.append(cell_styles)
            link_row.append(cell_links)
        if row:
            rows.append(row)
            styles.append(style_row)
            links.append(link_row)
    return rows, styles, links


def panel_has_only_heading_and_table(panel: Tag) -> bool:
    """Return true when a two-col panel can be safely replaced by a table image."""

    table = panel.find("table")
    if not isinstance(table, Tag):
        return False

    table_text = collapse_ws(table.get_text(" ", strip=True)).strip()
    for child in direct_tag_children(panel):
        if child.name in {"h2", "h3", "h4", "h5", "h6"}:
            continue
        if child is table:
            continue
        if child.find("table"):
            child_text = collapse_ws(child.get_text(" ", strip=True)).strip()
            if child_text == table_text:
                continue
        if collapse_ws(child.get_text(" ", strip=True)).strip():
            return False
    return True


def two_col_can_render_as_table_grid(node: Tag) -> bool:
    panels = direct_tag_children(node)
    return bool(panels) and all(panel_has_only_heading_and_table(panel) for panel in panels)


def add_two_col_layout(builder: Builder, node: Tag) -> None:
    panels: list[dict[str, Any]] = []
    for child in node.find_all(recursive=False):
        if not isinstance(child, Tag):
            continue
        table = child.find("table")
        if not isinstance(table, Tag):
            continue
        title_node = child.find(["h2", "h3", "h4", "h5", "h6"])
        title = collapse_ws(title_node.get_text(" ", strip=True) if title_node else "").strip()
        rows, styles, _links = table_from_html(table, first_column_bold=False)
        if rows:
            panels.append({"title": title, "rows": rows, "cell_styles": styles})

    if not panels:
        return

    builder.chart_counter += 1
    chart_id = f"CHART_IMAGE_{builder.chart_counter:02d}"
    placeholder = f"[[{chart_id}]]"
    start, end = builder.add(placeholder)
    builder.add("\n\n")
    image_file = f"chart_images/{chart_id.lower()}.png"
    builder.chart_images.append(
        {
            "id": chart_id,
            "kind": "two_col_table_grid",
            "panels": panels,
            "placeholder": placeholder,
            "placeholder_start": start,
            "placeholder_end": end,
            "image_file": image_file,
            "docs_width_pt": DOC_CONTENT_WIDTH_PT,
        }
    )
    builder.placeholders.append(
        {
            "id": chart_id,
            "kind": "chart_image",
            "text_to_find": placeholder,
            "start": start,
            "end": end,
        }
    )


def add_table_placeholder(
    builder: Builder,
    kind: str,
    rows: list[list[str]],
    styles: list[list[list[str]]] | None = None,
    links: list[list[list[dict[str, Any]]]] | None = None,
    bar_color: str | None = None,
) -> None:
    if not rows:
        return
    builder.table_counter += 1
    table_id = f"{kind.upper()}_{builder.table_counter:02d}"
    placeholder = f"[[{table_id}]]"
    start, end = builder.add(placeholder)
    builder.add("\n\n")
    table = {
        "id": table_id,
        "kind": kind,
        "rows": rows,
        "cell_styles": styles or [[[] for _ in row] for row in rows],
        "cell_links": links or [[[] for _ in row] for row in rows],
        "placeholder": placeholder,
        "placeholder_start": start,
        "placeholder_end": end,
    }
    if bar_color:
        table["bar_color"] = bar_color
    builder.tables.append(table)
    builder.placeholders.append(
        {
            "id": table_id,
            "kind": kind,
            "text_to_find": placeholder,
            "start": start,
            "end": end,
        }
    )


def first_text_for_selectors(node: Tag, selectors: list[str]) -> str:
    for selector in selectors:
        found = node.select_one(selector)
        if isinstance(found, Tag):
            text = collapse_ws(found.get_text(" ", strip=True)).strip()
            if text:
                return text
    return ""


def metric_nodes(node: Tag) -> list[Tag]:
    direct_metrics = direct_children_with_class(node, "metric")
    if direct_metrics:
        return direct_metrics
    return [metric for metric in node.select(".metric") if isinstance(metric, Tag)]


def add_metric_row(builder: Builder, node: Tag) -> None:
    row: list[str] = []
    style_row: list[list[str]] = []
    for metric in metric_nodes(node):
        value = first_text_for_selectors(metric, [".value", ".metric-value", ".k", "strong", "b"])
        label = first_text_for_selectors(metric, [".label", ".metric-label", ".l", "span"])
        note = first_text_for_selectors(metric, [".note", ".metric-note", ".sub"])
        pieces = [piece for piece in (value, label, note) if piece]
        if not pieces:
            pieces = [collapse_ws(metric.get_text(" ", strip=True)).strip()]
        row.append("\n".join(piece for piece in pieces if piece))
        style_row.append(["metric"])
    if not row:
        return
    add_table_placeholder(builder, "metric_cards", [row], [style_row])


def add_pill_row(builder: Builder, node: Tag) -> None:
    labels = [collapse_ws(pill.get_text(" ", strip=True)).strip() for pill in node.select(".pill")]
    labels = [label for label in labels if label]
    if not labels:
        return
    start, end = builder.add(" | ".join(labels))
    builder.add("\n")
    builder.blocks.append({"start": start, "end": end + 1, "type": "muted"})


def add_muted_text(builder: Builder, text: str) -> None:
    text = collapse_ws(text).strip()
    if not text:
        return
    start, end = builder.add(text)
    builder.add("\n")
    builder.blocks.append({"start": start, "end": end + 1, "type": "muted"})


def add_embedded_image(builder: Builder, img: Tag, caption: str = "") -> bool:
    src = str(img.get("src") or "").strip()
    if not src:
        return False

    builder.chart_counter += 1
    chart_id = f"CHART_IMAGE_{builder.chart_counter:02d}"
    placeholder = f"[[{chart_id}]]"
    start, end = builder.add(placeholder)
    builder.add("\n\n")
    image_file = f"chart_images/{chart_id.lower()}.png"
    builder.chart_images.append(
        {
            "id": chart_id,
            "kind": "embedded_image",
            "src": src,
            "alt": collapse_ws(str(img.get("alt") or "")).strip(),
            "caption": caption,
            "placeholder": placeholder,
            "placeholder_start": start,
            "placeholder_end": end,
            "image_file": image_file,
            "docs_width_pt": DOC_CONTENT_WIDTH_PT,
        }
    )
    builder.placeholders.append(
        {
            "id": chart_id,
            "kind": "chart_image",
            "text_to_find": placeholder,
            "start": start,
            "end": end,
        }
    )
    return True


def figure_caption_text(node: Tag) -> str:
    parts: list[str] = []
    for selector in ["figcaption", ".caption", ".spark-axis"]:
        for caption_node in node.select(selector):
            if isinstance(caption_node, Tag):
                text = collapse_ws(caption_node.get_text(" ", strip=True)).strip()
                if text and text not in parts:
                    parts.append(text)
    return " ".join(parts)


def add_figure(builder: Builder, node: Tag) -> bool:
    img = node.find("img")
    if isinstance(img, Tag):
        caption = figure_caption_text(node)
        added = add_embedded_image(builder, img, caption=caption)
        if added and caption:
            add_muted_text(builder, caption)
        return added

    svg = node.find("svg")
    if isinstance(svg, Tag):
        add_svg_chart(builder, svg)
        caption = figure_caption_text(node)
        if caption:
            add_muted_text(builder, caption)
        return True

    return False


def css_bar_widths(stylesheet_text: str) -> dict[str, float]:
    widths: dict[str, float] = {}
    for selectors, body in CSS_RULE_RE.findall(stylesheet_text):
        match = re.search(r"width\s*:\s*([0-9.]+)%", body)
        if not match:
            continue
        pct = float(match.group(1))
        for selector in selectors.split(","):
            class_names = re.findall(r"\.([A-Za-z0-9_-]+)", selector)
            if not class_names or not ({"bar", "fill", "bar-fill"} & set(class_names)):
                continue
            for class_name in class_names:
                if class_name not in {"bar", "fill", "bar-fill"}:
                    widths[class_name] = pct
    return widths


def bar_width_pct(fill: Tag | None, width_by_class: dict[str, float]) -> float:
    if not isinstance(fill, Tag):
        return 100.0
    match = re.search(r"width\s*:\s*([0-9.]+)", str(fill.get("style", "")))
    if match:
        return float(match.group(1))
    for class_name in classes(fill):
        if class_name in width_by_class:
            return width_by_class[class_name]
    return 100.0


def add_bar_chart(builder: Builder, node: Tag, width_by_class: dict[str, float]) -> None:
    chart_rows: list[dict[str, Any]] = []
    bar_color = "blue" if node.select_one(".fill.blue, .bar-fill.blue, .bar.blue") else "accent"
    for line in node.select(".bar-line, .bar-row"):
        spans = line.find_all("span")
        label_node = line.select_one(".bar-label, .label")
        value_node = line.select_one(".bar-value, .value")
        bar_head = line.select_one(".bar-head")
        if isinstance(bar_head, Tag):
            label_node = label_node or bar_head.find("span")
            value_node = value_node or bar_head.find("strong") or bar_head.find("b")
        direct_parts = [
            child
            for child in direct_tag_children(line)
            if "bar-track" not in classes(child)
            and not (classes(child) & {"bar", "fill", "bar-fill"})
            and collapse_ws(child.get_text(" ", strip=True)).strip()
        ]
        if not isinstance(label_node, Tag) and spans:
            label_node = spans[0]
        if not isinstance(label_node, Tag) and direct_parts:
            label_node = direct_parts[0]
        if not isinstance(value_node, Tag) and len(spans) >= 2:
            value_node = spans[-1]
        if not isinstance(value_node, Tag) and len(direct_parts) >= 2:
            value_node = direct_parts[-1]
        if not isinstance(label_node, Tag) or not isinstance(value_node, Tag):
            continue
        label = collapse_ws(label_node.get_text(" ", strip=True))
        value = collapse_ws(value_node.get_text(" ", strip=True))
        fill = line.select_one(".fill, .bar-fill, .bar")
        pct = bar_width_pct(fill, width_by_class)
        chart_rows.append({"label": label, "value": value, "pct": pct})
    if not chart_rows:
        return

    if builder.chart_mode == "table":
        rows: list[list[str]] = []
        style_rows: list[list[list[str]]] = []
        for row in chart_rows:
            blocks = max(1, round(row["pct"] / 5))
            rows.append([row["label"], "█" * blocks, row["value"]])
            style_rows.append([[], ["bar"], []])
        add_table_placeholder(builder, "bar_chart", rows, style_rows, bar_color=bar_color)
        return

    builder.chart_counter += 1
    chart_id = f"CHART_IMAGE_{builder.chart_counter:02d}"
    placeholder = f"[[{chart_id}]]"
    start, end = builder.add(placeholder)
    builder.add("\n\n")
    image_file = f"chart_images/{chart_id.lower()}.png"
    builder.chart_images.append(
        {
            "id": chart_id,
            "kind": "bar_chart",
            "aria_label": node.get("aria-label", ""),
            "rows": chart_rows,
            "bar_color": bar_color,
            "placeholder": placeholder,
            "placeholder_start": start,
            "placeholder_end": end,
            "image_file": image_file,
        }
    )
    builder.placeholders.append(
        {
            "id": chart_id,
            "kind": "chart_image",
            "text_to_find": placeholder,
            "start": start,
            "end": end,
        }
    )


def svg_dimensions(svg: Tag) -> tuple[int, int]:
    width = svg.get("width")
    height = svg.get("height")
    try:
        return int(float(str(width))), int(float(str(height)))
    except (TypeError, ValueError):
        pass
    view_box = svg.get("viewBox") or svg.get("viewbox")
    if view_box:
        parts = str(view_box).replace(",", " ").split()
        if len(parts) == 4:
            try:
                return int(float(parts[2])), int(float(parts[3]))
            except ValueError:
                pass
    return 1000, 600


def inline_svg_report_styles(svg_markup: str) -> str:
    """Apply report chart CSS classes as explicit SVG attributes.

    Sanitized reports commonly keep chart colors in the page stylesheet while
    SVG elements only carry classes. Once the SVG is extracted into the Docs
    conversion plan, renderers that do not have the original stylesheet can
    silently lose bars or labels. Inlining the known report chart classes keeps
    the generated PNG visually faithful and renderer-independent.
    """

    soup = BeautifulSoup(svg_markup, "xml")
    svg = soup.find("svg") or soup
    for el in svg.find_all(True):
        merged: dict[str, str] = {}
        for class_name in classes(el):
            merged.update(SVG_REPORT_STYLE_DEFAULTS.get(class_name, {}))
        for attr, value in merged.items():
            if el.get(attr) is None:
                el[attr] = value
    return str(svg)


def add_svg_chart(builder: Builder, node: Tag) -> None:
    svg = node if node.name == "svg" else node.find("svg")
    if not isinstance(svg, Tag):
        return

    builder.chart_counter += 1
    chart_id = f"CHART_IMAGE_{builder.chart_counter:02d}"
    placeholder = f"[[{chart_id}]]"
    start, end = builder.add(placeholder)
    builder.add("\n\n")

    width_px, height_px = svg_dimensions(svg)
    docs_height = round(DOC_CONTENT_WIDTH_PT * height_px / width_px, 1) if width_px else 240
    image_file = f"chart_images/{chart_id.lower()}.png"
    builder.chart_images.append(
        {
            "id": chart_id,
            "kind": "svg",
            "aria_label": svg.get("aria-label", node.get("aria-label", "")),
            "svg_markup": inline_svg_report_styles(str(svg)),
            "source_width_px": width_px,
            "source_height_px": height_px,
            "placeholder": placeholder,
            "placeholder_start": start,
            "placeholder_end": end,
            "image_file": image_file,
            "docs_width_pt": DOC_CONTENT_WIDTH_PT,
            "docs_height_pt": docs_height,
        }
    )
    builder.placeholders.append(
        {
            "id": chart_id,
            "kind": "chart_image",
            "text_to_find": placeholder,
            "start": start,
            "end": end,
        }
    )


def parse_html(path: Path, chart_mode: str = "image") -> dict[str, Any]:
    require_bs4()
    raw_html = path.read_text(encoding="utf-8")
    soup = BeautifulSoup(raw_html, "html.parser")
    root = soup.find("main") or soup.body or soup
    builder = Builder(chart_mode=chart_mode)
    stylesheet_text = "\n".join(style.get_text("\n") for style in soup.find_all("style"))
    first_column_bold = table_first_column_is_bold(stylesheet_text)
    bar_width_by_class = css_bar_widths(stylesheet_text)

    blockish_tags = {"h1", "h2", "h3", "h4", "p", "table", "ul", "ol", "figure", "img", "svg"}
    blockish_classes = {
        "bar-chart",
        "charts",
        "callout",
        "chart",
        "figure",
        "implication",
        "bars",
        "metric-grid",
        "metrics",
        "pillrow",
        "summary",
        "spark",
        "two-col",
    }

    def has_blockish_child(node: Tag) -> bool:
        for child in direct_tag_children(node):
            if child.name in blockish_tags or classes(child) & blockish_classes:
                return True
        if node.find(list(blockish_tags)):
            return True
        return any(node.find(class_=class_name) for class_name in blockish_classes)

    def process_children(node: Tag) -> None:
        for child in node.children:
            if isinstance(child, Tag):
                process_node(child)

    def add_summary_callout(builder: Builder, node: Tag) -> None:
        start = builder.offset
        append_inline(builder, node)
        end = builder.offset
        if end > start:
            builder.add("\n")
            builder.blocks.append({"start": start, "end": end + 1, "type": "summary_callout"})

    def process_node(node: Tag) -> None:
        node_classes = classes(node)
        if "two-col" in node_classes:
            if two_col_can_render_as_table_grid(node):
                add_two_col_layout(builder, node)
            else:
                builder.two_col_text_blocks += 1
                process_children(node)
            return
        if node.name in {"h1", "h2", "h3", "h4"}:
            add_heading(builder, node)
            return
        if node.name == "figure" or "figure" in node_classes:
            if add_figure(builder, node):
                return
            process_children(node)
            return
        if node.name == "img":
            add_embedded_image(builder, node)
            return
        if node.name == "p":
            if "note" in node_classes:
                block_type = "note"
            elif "source" in node_classes or "source-list" in node_classes:
                block_type = "source_list"
            elif "sub" in node_classes:
                block_type = "muted"
            else:
                block_type = None
            add_paragraph(builder, node, block_type)
            return
        if (
            "metric-grid" in node_classes
            or "metrics" in node_classes
            or direct_children_with_class(node, "metric")
        ):
            add_metric_row(builder, node)
            return
        if node.name == "table":
            rows, styles, links = table_from_html(node, first_column_bold=first_column_bold)
            add_table_placeholder(builder, "table", rows, styles, links)
            return
        if node.name in {"ul", "ol"}:
            start = builder.offset
            for li in node.find_all("li", recursive=False):
                li_start = builder.offset
                append_inline(builder, li)
                if builder.offset > li_start:
                    builder.add("\n")
            end = builder.offset
            builder.add("\n")
            if end > start:
                builder.lists.append({"start": start, "end": end, "ordered": node.name == "ol"})
            return
        child_tags = direct_tag_children(node)
        if "pillrow" in node_classes or (
            child_tags and all("pill" in classes(child) for child in child_tags)
        ):
            add_pill_row(builder, node)
            return
        if "callout" in node_classes or "implication" in node_classes:
            add_summary_callout(builder, node)
            return
        if "bar-chart" in node_classes or "bars" in node_classes:
            add_bar_chart(builder, node, bar_width_by_class)
            return
        if "chart" in node_classes and node.find("svg"):
            add_svg_chart(builder, node)
            return
        if node.name == "svg":
            add_svg_chart(builder, node)
            return

        if not has_blockish_child(node) and collapse_ws(node.get_text(" ", strip=True)).strip():
            add_paragraph(builder, node)
            return
        process_children(node)

    for child in root.children:
        if isinstance(child, Tag):
            process_node(child)

    title = (soup.title.get_text(" ", strip=True) if soup.title else "").strip()
    h1 = root.find("h1")
    if h1:
        title = collapse_ws(h1.get_text(" ", strip=True)).strip() or title
    two_col_blocks = root.select(".two-col")
    bar_blocks = [block for block in root.select(".bar-chart, .bars") if block.name != "svg"]

    return {
        "source_html": str(path),
        "title": title,
        "skeleton_text": builder.text().rstrip() + "\n",
        "headings": builder.headings,
        "inline_styles": builder.inline_styles,
        "blocks": builder.blocks,
        "lists": builder.lists,
        "placeholders": builder.placeholders,
        "tables": builder.tables,
        "chart_images": builder.chart_images,
        "counts": {
            "headings": len(builder.headings),
            "inline_styles": len(builder.inline_styles),
            "blocks": len(builder.blocks),
            "lists": len(builder.lists),
            "tables": len(builder.tables),
            "chart_images": len(builder.chart_images),
            "two_col_source_blocks": len(two_col_blocks),
            "two_col_image_blocks": sum(
                1 for chart in builder.chart_images if chart.get("kind") == "two_col_table_grid"
            ),
            "two_col_text_blocks": builder.two_col_text_blocks,
            "embedded_image_blocks": sum(
                1 for chart in builder.chart_images if chart.get("kind") == "embedded_image"
            ),
            "svg_image_blocks": sum(
                1 for chart in builder.chart_images if chart.get("kind") == "svg"
            ),
            "bar_source_blocks": len(bar_blocks),
            "bar_image_blocks": sum(
                1 for chart in builder.chart_images if chart.get("kind") == "bar_chart"
            ),
            "bar_table_blocks": sum(
                1 for table in builder.tables if table.get("kind") == "bar_chart"
            ),
            "images": len(root.find_all("img")),
            "svgs": len(root.find_all("svg")),
            "canvas": len(root.find_all("canvas")),
        },
        "source_flags": {
            "auth_page_detected": "login.microsoftonline.com" in raw_html
            or title.strip().lower() == "sign in to your account"
        },
    }

from __future__ import annotations

import re
from pathlib import Path
from typing import Any

from .constants import BAR_CHART_HEX_COLORS, DOC_CONTENT_WIDTH_PT, NEUTRAL_SVG_COLORS
from .table_utils import table_column_widths


def add_preflight_check(
    checks: list[dict[str, Any]],
    *,
    name: str,
    passed: bool,
    severity: str,
    message: str,
    details: dict[str, Any] | None = None,
) -> None:
    checks.append(
        {
            "name": name,
            "status": "passed" if passed else "failed",
            "severity": severity,
            "message": message,
            "details": details or {},
        }
    )


def hex_to_rgb_tuple(value: str) -> tuple[int, int, int]:
    raw = value.strip().lstrip("#")
    return (int(raw[0:2], 16), int(raw[2:4], 16), int(raw[4:6], 16))


def is_expected_svg_mark_color(color: str) -> bool:
    normalized = color.lower()
    if normalized in BAR_CHART_HEX_COLORS:
        return True
    if normalized in NEUTRAL_SVG_COLORS:
        return False
    red, green, blue = hex_to_rgb_tuple(normalized)
    return max(red, green, blue) - min(red, green, blue) >= 45 and max(red, green, blue) < 245


def expected_chart_colors(chart: dict[str, Any]) -> list[tuple[int, int, int]]:
    """Return colors that prove the rendered PNG kept the source visual marks.

    This is intentionally conservative: it checks report-specific bar and
    positive/negative table colors, plus saturated SVG colors, but ignores text,
    gridline, and background colors that would let a broken chart pass.
    """
    kind = chart.get("kind")
    if kind == "bar_chart":
        return [hex_to_rgb_tuple("#1d4ed8" if chart.get("bar_color") == "blue" else "#0f766e")]
    if kind == "two_col_table_grid":
        has_positive = any(
            "positive" in cell_styles
            for panel in chart.get("panels", [])
            for row_styles in panel.get("cell_styles", [])
            for cell_styles in row_styles
        )
        has_negative = any(
            "negative" in cell_styles
            for panel in chart.get("panels", [])
            for row_styles in panel.get("cell_styles", [])
            for cell_styles in row_styles
        )
        colors: list[str] = []
        if has_positive:
            colors.append("#26845f")
        if has_negative:
            colors.append("#c75146")
        return [hex_to_rgb_tuple(color) for color in colors]
    if kind == "svg":
        markup = str(chart.get("svg_markup", "")).lower()
        return [
            hex_to_rgb_tuple(color)
            for color in sorted(set(re.findall(r"#[0-9a-f]{6}", markup)))
            if is_expected_svg_mark_color(color)
        ]
    return []


def image_pixels(image: Any) -> list[tuple[int, int, int]]:
    if hasattr(image, "get_flattened_data"):
        return list(image.get_flattened_data())
    return list(image.getdata())


def count_expected_color_hits(
    image: Any,
    expected_colors: list[tuple[int, int, int]],
    tolerance: int = 40,
) -> dict[str, int]:
    if not expected_colors:
        return {}

    color_hits = {"#%02x%02x%02x" % color: 0 for color in expected_colors}
    color_table = image.getcolors(maxcolors=image.size[0] * image.size[1])
    if color_table is None:
        pixel_iter = (
            image.get_flattened_data() if hasattr(image, "get_flattened_data") else image.getdata()
        )
        color_table = [(1, pixel) for pixel in pixel_iter]
    for count, pixel in color_table:
        for expected in expected_colors:
            if sum(abs(pixel[channel] - expected[channel]) for channel in range(3)) <= tolerance:
                color_hits["#%02x%02x%02x" % expected] += count
    return color_hits


def inspect_image_object(
    image: Any,
    expected_colors: list[tuple[int, int, int]],
    exact_color_scan: bool = False,
) -> dict[str, Any]:
    """Return cheap local evidence that a rendered image is usable in Docs."""
    from PIL import Image

    rgb_image = image.convert("RGB")
    width, height = rgb_image.size
    sample = rgb_image.resize((min(width, 160), min(height, 160)))
    pixels = image_pixels(sample)
    # Full-image color scans are expensive on large chart screenshots. Use
    # exact scans only for rendered table grids, where tiny red/green text is
    # easy to miss after downsampling.
    if exact_color_scan:
        color_image = rgb_image
    else:
        color_image = rgb_image.resize(
            (min(width, 160), min(height, 160)),
            getattr(Image, "Resampling", Image).NEAREST,
        )
    color_hits = count_expected_color_hits(color_image, expected_colors)

    total = max(1, len(pixels))
    extrema = sample.getextrema()
    uniform = all(channel_min == channel_max for channel_min, channel_max in extrema)
    non_white = sum(1 for r, g, b in pixels if min(r, g, b) < 245)
    non_white_ratio = non_white / total

    return {
        "width_px": width,
        "height_px": height,
        "uniform": uniform,
        "non_white_ratio": round(non_white_ratio, 4),
        "expected_color_hits": color_hits,
    }


def inspect_png(
    path: Path, expected_colors: list[tuple[int, int, int]], exact_color_scan: bool = False
) -> dict[str, Any]:
    try:
        from PIL import Image
    except ImportError as exc:  # pragma: no cover - dependency check path
        raise RuntimeError("PNG preflight requires pillow") from exc

    with Image.open(path) as image:
        return inspect_image_object(image, expected_colors, exact_color_scan=exact_color_scan)


def build_preflight_checks(
    manifest: dict[str, Any],
    out_dir: Path,
) -> dict[str, Any]:
    """Build the local quality gate that must pass before Google Docs writes."""
    checks: list[dict[str, Any]] = []
    doc_width = DOC_CONTENT_WIDTH_PT

    add_preflight_check(
        checks,
        name="source_is_report_html",
        passed=not manifest.get("source_flags", {}).get("auth_page_detected", False),
        severity="error",
        message="Source HTML must be the report, not an auth/login page.",
    )

    source_two_col = manifest["counts"].get("two_col_source_blocks", 0)
    rendered_two_col = manifest["counts"].get("two_col_image_blocks", 0)
    text_two_col = manifest["counts"].get("two_col_text_blocks", 0)
    add_preflight_check(
        checks,
        name="two_col_blocks_preserved",
        passed=source_two_col == rendered_two_col + text_two_col,
        severity="error",
        message="Every source .two-col block should map to either one rendered multi-column block or preserved native text blocks.",
        details={
            "source_two_col_blocks": source_two_col,
            "rendered_two_col_blocks": rendered_two_col,
            "native_text_two_col_blocks": text_two_col,
        },
    )

    source_svgs = manifest["counts"].get("svgs", 0)
    rendered_svgs = manifest["counts"].get("svg_image_blocks", 0)
    add_preflight_check(
        checks,
        name="svg_blocks_preserved",
        passed=source_svgs == rendered_svgs,
        severity="error",
        message="Every source SVG visual should map to one rendered DOCX image.",
        details={"source_svgs": source_svgs, "rendered_svg_images": rendered_svgs},
    )

    source_bars = manifest["counts"].get("bar_source_blocks", 0)
    rendered_bars = manifest["counts"].get("bar_image_blocks", 0)
    table_bars = manifest["counts"].get("bar_table_blocks", 0)
    add_preflight_check(
        checks,
        name="bar_chart_blocks_preserved",
        passed=source_bars == rendered_bars + table_bars,
        severity="error",
        message="Every source bar-chart block should map to one rendered DOCX image or native table fallback.",
        details={
            "source_bar_blocks": source_bars,
            "rendered_bar_images": rendered_bars,
            "native_bar_tables": table_bars,
        },
    )

    for chart in manifest.get("chart_images", []):
        width = float(chart.get("docs_width_pt", doc_width))
        add_preflight_check(
            checks,
            name=f"{chart['id']}_width_cap",
            passed=width <= doc_width,
            severity="error",
            message="Rendered image width is capped to the report text column.",
            details={"docs_width_pt": width, "doc_width_pt": doc_width},
        )
        if chart.get("kind") == "two_col_table_grid":
            missing_titles = [
                idx
                for idx, panel in enumerate(chart.get("panels", []), start=1)
                if not str(panel.get("title", "")).strip()
            ]
            add_preflight_check(
                checks,
                name=f"{chart['id']}_panel_titles",
                passed=not missing_titles,
                severity="error",
                message="Rendered multi-column table panels preserve visible source titles.",
                details={"missing_title_panel_indices": missing_titles},
            )

        image_path = out_dir / chart["image_file"]
        add_preflight_check(
            checks,
            name=f"{chart['id']}_png_exists",
            passed=image_path.exists(),
            severity="error",
            message="Every chart placeholder has a rendered local PNG.",
            details={"image_file": chart["image_file"]},
        )
        if image_path.exists():
            try:
                stats = chart.get("render_preflight_stats") or inspect_png(
                    image_path,
                    expected_chart_colors(chart),
                    exact_color_scan=chart.get("kind") == "two_col_table_grid",
                )
                color_hits = stats.get("expected_color_hits", {})
                expected_colors_present = not color_hits or any(
                    count > 0 for count in color_hits.values()
                )
                add_preflight_check(
                    checks,
                    name=f"{chart['id']}_png_not_blank",
                    passed=not stats["uniform"] and stats["non_white_ratio"] > 0.002,
                    severity="error",
                    message="Rendered image is not blank or near-empty.",
                    details=stats,
                )
                add_preflight_check(
                    checks,
                    name=f"{chart['id']}_expected_colors_visible",
                    passed=expected_colors_present,
                    severity="error",
                    message="Expected chart/table colors are visible in the rendered PNG.",
                    details=stats,
                )
            except Exception as exc:
                add_preflight_check(
                    checks,
                    name=f"{chart['id']}_png_inspection",
                    passed=False,
                    severity="error",
                    message=f"Could not inspect rendered PNG: {exc}",
                    details={"image_file": chart["image_file"]},
                )

    table_width_failures: list[dict[str, Any]] = []
    for table in manifest.get("tables", []):
        rows = table.get("rows", [])
        if not rows:
            continue
        widths = table_column_widths(table, len(rows[0]))
        total = round(sum(widths), 1)
        if total > doc_width:
            table_width_failures.append(
                {"id": table["id"], "total_width_pt": total, "column_widths_pt": widths}
            )
    add_preflight_check(
        checks,
        name="native_table_width_cap",
        passed=not table_width_failures,
        severity="error",
        message="Native table column widths do not exceed the report text column.",
        details={"failures": table_width_failures},
    )

    image_size_failures = []
    for chart in manifest.get("chart_images", []):
        width = chart.get("docs_width_pt")
        height = chart.get("docs_height_pt")
        if width is None or height is None or float(width) > doc_width:
            image_size_failures.append({"id": chart.get("id"), "width": width, "height": height})
    add_preflight_check(
        checks,
        name="docx_images_have_explicit_sizes",
        passed=not image_size_failures,
        severity="error",
        message="DOCX image entries carry explicit text-width object sizes.",
        details={"failures": image_size_failures},
    )

    chart_count = len(manifest.get("chart_images", []))
    add_preflight_check(
        checks,
        name="docx_image_count_matches_manifest",
        passed=chart_count
        == len(
            [
                chart
                for chart in manifest.get("chart_images", [])
                if chart.get("image_file") and chart.get("docs_width_pt")
            ]
        ),
        severity="error",
        message="Every rendered image has the metadata needed for one DOCX image.",
        details={
            "manifest_chart_images": chart_count,
            "docx_image_entries": len(
                [
                    chart
                    for chart in manifest.get("chart_images", [])
                    if chart.get("image_file") and chart.get("docs_width_pt")
                ]
            ),
        },
    )

    errors = [
        check for check in checks if check["severity"] == "error" and check["status"] == "failed"
    ]
    warnings = [
        check for check in checks if check["severity"] == "warning" and check["status"] == "failed"
    ]
    return {
        "status": "failed" if errors else "passed",
        "doc_content_width_pt": doc_width,
        "summary": {
            "checks": len(checks),
            "errors": len(errors),
            "warnings": len(warnings),
            "tables": len(manifest.get("tables", [])),
            "chart_images": chart_count,
        },
        "errors": errors,
        "warnings": warnings,
        "checks": checks,
    }

from __future__ import annotations

import re
from typing import Any

from .constants import DOC_CONTENT_WIDTH_PT

NUMERIC_TABLE_CELL_RE = re.compile(r"^[\s$%+,\-()./:0-9xXkKmMbBtT]+$")


def table_column_widths(table: dict[str, Any], columns: int) -> list[float]:
    if columns <= 0:
        return []

    total_width = float(table.get("docs_width_pt", DOC_CONTENT_WIDTH_PT))
    kind = table.get("kind")
    if kind == "metric_cards" or columns <= 4:
        width = total_width / columns
        return [round(width, 1)] * columns

    if columns == 5:
        first = 120.0
    elif columns >= 6:
        first = 90.0
    else:
        first = total_width / columns

    first = min(first, total_width / columns * 1.15)
    remaining = (total_width - first) / (columns - 1)
    return [round(first, 1)] + [round(remaining, 1)] * (columns - 1)


def table_cell_is_numeric(text: str) -> bool:
    stripped = text.strip()
    return bool(
        stripped
        and any(char.isdigit() for char in stripped)
        and NUMERIC_TABLE_CELL_RE.match(stripped)
    )


def numeric_table_columns(rows: list[list[str]]) -> set[int]:
    if not rows:
        return set()
    numeric_columns: set[int] = set()
    for column_index in range(len(rows[0])):
        values = [
            row[column_index]
            for row in rows[1:]
            if column_index < len(row) and row[column_index].strip()
        ]
        if values and all(table_cell_is_numeric(value) for value in values):
            numeric_columns.add(column_index)
    return numeric_columns

